/* Vacation UI. Data and drafts stay in memory; the separate private workbook is authoritative. */
(() => {
 'use strict';
 const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const iso=v=>v==null||v===''?'':new Date(Date.UTC(1899,11,30)+Math.floor(Number(v))*86400000).toISOString().slice(0,10);
 const clock=v=>v==null||v===''?'':`${String(Math.floor((Number(v)%1)*1440+0.0001)/60|0).padStart(2,'0')}:${String(Math.round((Number(v)%1)*1440)%60).padStart(2,'0')}`;
 const nice=v=>new Intl.DateTimeFormat('es-ES',{weekday:'long',day:'numeric',month:'long',timeZone:'UTC'}).format(new Date(iso(v)+'T12:00:00Z'));
 const safe=s=>{try{const u=new URL(s);return u.protocol==='https:'?u.href:'#';}catch{return '#';}};
 let data=null,host=null,api=null,error='',pending=false,epoch=0,selected='all',scope='active',dialog=null,editor=null,loading=null;
 const done=p=>['Realizado','Cancelado'].includes(p.Estado);
 const active=()=>data.plans.filter(p=>scope==='all'||!done(p));
 function initDialog(){if(dialog)return;dialog=document.createElement('dialog');dialog.id='vac-dialog';dialog.className='vac-dialog';dialog.setAttribute('aria-labelledby','vac-editor-title');document.body.appendChild(dialog);dialog.addEventListener('cancel',e=>{e.preventDefault();close();});dialog.addEventListener('input',()=>{if(editor)editor.dirty=true;});dialog.addEventListener('click',e=>{if(e.target.closest('[data-vac-close]'))close();});dialog.addEventListener('submit',save);}
 function close(){if(pending)return;if(editor?.dirty&&!confirm('¿Cerrar y descartar los cambios sin guardar?'))return;dialog.close();dialog.innerHTML='';editor=null;}
 function status(p){return `<span class="vac-status ${p.Estado==='Confirmado'?'confirmed':p.Estado==='En espera'?'waiting':''}">${esc(p.Estado)}</span>`;}
 function card(p,agenda=false){const hour=clock(p['Hora inicio']),end=clock(p['Hora fin']);return `<article class="vac-plan ${agenda?'vac-scheduled':''}">${agenda?`<div class="vac-time">${hour||'Sin hora'}${end?`<small>hasta ${end}</small>`:''}</div>`:''}<div class="vac-plan-body"><div class="vac-plan-meta"><span>${esc(p.Tipo)}</span>${status(p)}</div><h3>${esc(p.Plan)}</h3>${p.Lugar?`<p class="vac-location">${esc(p.Lugar)}</p>`:''}${p['Depende de']?`<p class="vac-dependency">${esc(p['Depende de'])}</p>`:''}<div class="vac-plan-bottom">${p.Personas?`<span>${esc(p.Personas)}</span>`:'<span></span>'}<button class="text-button" data-vac-edit="${esc(p.ID)}">Ver y editar <span aria-hidden="true">↗</span></button></div></div></article>`;}
 function draw(){if(!host?.isConnected)return;
  if(!data){host.innerHTML=`<section class="vac-loading"><p>${error?esc(error):'Leyendo los planes del viaje…'}</p>${error?'<button class="button light" data-vac-refresh>Reintentar</button>':''}</section>`;return;}
  const trip=data.trip,plans=active(),loose=plans.filter(p=>p['Fecha inicio']==null),scheduled=plans.filter(p=>p['Fecha inicio']!=null).sort((a,b)=>a['Fecha inicio']-b['Fecha inicio']||(a['Hora inicio']??2)-(b['Hora inicio']??2));
  const dates=[];for(let d=Math.floor(trip.Inicio);d<=Math.floor(trip.Fin)&&dates.length<60;d++)dates.push(d);
  const count=plans.filter(p=>p.Estado==='Confirmado').length;
  host.innerHTML=`<div class="vac-app"><header class="vac-hero"><div><p class="vac-eyebrow">TU PRÓXIMA ESCAPADA</p><h1>${esc(trip.Nombre)}</h1><p class="vac-dates">${esc(nice(trip.Inicio))} — ${esc(nice(trip.Fin))}</p><p class="vac-intro">${esc(trip.Notas||'Pon fecha a tus planes, con espacio para improvisar.')}</p></div><div class="vac-hero-actions"><button class="button dark" data-vac-new>+ Añadir plan</button><a class="text-button" href="${esc(safe(data.sheetUrl))}" target="_blank" rel="noopener noreferrer">Abrir datos del viaje ↗</a></div><span class="vac-landscape" aria-hidden="true"><i></i><i></i><i></i></span></header><div class="vac-toolbar"><p><b>${count}</b> ${count===1?'plan confirmado':'planes confirmados'} <span>·</span> <b>${loose.length}</b> por encajar</p><div><label class="sr-label" for="vac-scope">Planes mostrados</label><select id="vac-scope"><option value="active" ${scope==='active'?'selected':''}>Planes abiertos</option><option value="all" ${scope==='all'?'selected':''}>Todos, incluidos cerrados</option></select><button class="text-button" data-vac-refresh>Actualizar</button></div></div>${error?`<p class="vac-error" role="alert">${esc(error)}</p>`:''}<nav class="vac-days" aria-label="Días de vacaciones"><button data-vac-day="all" class="${selected==='all'?'selected':''}"><small>EL VIAJE</small><b>Todo</b></button>${dates.map(d=>`<button data-vac-day="${d}" class="${Number(selected)===d?'selected':''}"><small>${esc(new Intl.DateTimeFormat('es-ES',{weekday:'short',timeZone:'UTC'}).format(new Date(iso(d)+'T12:00:00Z')))}</small><b>${new Date(iso(d)+'T12:00:00Z').getUTCDate()}</b><span>${plans.filter(p=>p['Fecha inicio']!=null&&Math.floor(p['Fecha inicio'])===d).length||'—'}</span></button>`).join('')}</nav><div class="vac-columns"><section class="vac-agenda"><div class="vac-section-heading"><div><p class="vac-eyebrow">CON FECHA</p><h2>La agenda</h2></div><span>Hora local · Madrid</span></div>${dates.filter(d=>selected==='all'||Number(selected)===d).map(d=>{const ps=scheduled.filter(p=>Math.floor(p['Fecha inicio'])===d);return `<section class="vac-agenda-day"><h3 class="vac-date-title">${esc(nice(d))}</h3>${ps.length?ps.map(p=>card(p,true)).join(''):`<div class="vac-free"><p>Sin planes con fecha para este día.</p><button class="text-button" data-vac-new-day="${d}">Añadir un plan</button></div>`}</section>`;}).join('')}</section><aside class="vac-unscheduled"><div class="vac-section-heading"><div><p class="vac-eyebrow">A TU RITMO</p><h2>Por encajar</h2></div><span>${loose.length}</span></div><p class="vac-hint">Ideas y planes que esperan fecha o una confirmación.</p>${loose.length?loose.map(p=>card(p)).join(''):'<p class="vac-free">Todos los planes tienen fecha.</p>'}</aside></div><footer class="vac-foot">Última lectura: ${esc(new Intl.DateTimeFormat('es-ES',{day:'numeric',month:'short',hour:'2-digit',minute:'2-digit',timeZone:'Europe/Madrid'}).format(new Date(data.fetchedAt)))} <a href="https://hexabor.github.io/arc-personal-hub/mapa-vacaciones.html">Árbol de fases</a></footer></div>`;
 }
 async function refresh(){if(loading)return loading;const current=epoch;error='';loading=(async()=>{try{const fresh=await api('getVacationData');if(current!==epoch)return;data=fresh;}catch(e){if(current!==epoch)return;error=e.message||'No se han podido leer los planes.';}finally{if(current===epoch){loading=null;draw();}}})();return loading;}
 function formField(key,label,value,type='text',extra=''){return `<label class="vac-field">${label}<input name="${esc(key)}" type="${type}" value="${esc(value??'')}" ${extra}></label>`;}
 function edit(id,day){initDialog();const p=id?data.plans.find(p=>p.ID===id):null;if(id&&!p)return;editor={id:p?.ID||null,version:p?._version||null,dirty:false,payload:null};
  const lo=iso(data.trip.Inicio),hi=iso(data.trip.Fin),pval=k=>p?.[k]??'';
  dialog.innerHTML=`<div class="vac-editor-head"><span class="vac-eyebrow">${p?'PLAN DEL VIAJE':'UN PLAN NUEVO'}</span><button type="button" class="icon-button" data-vac-close aria-label="Cerrar plan">×</button></div><h2 id="vac-editor-title">${p?'Editar plan':'Añadir plan'}</h2><form id="vac-edit-form"><fieldset><div class="vac-form-grid">${formField('Plan','Plan',pval('Plan'),'text','required maxlength="250" class="vac-wide"')}<label class="vac-field">Tipo<select name="Tipo">${data.types.map(s=>`<option ${s===pval('Tipo')?'selected':''}>${esc(s)}</option>`).join('')}</select></label><label class="vac-field">Estado<select name="Estado">${data.statuses.map(s=>`<option ${(p?.Estado||'Por concretar')===s?'selected':''}>${esc(s)}</option>`).join('')}</select></label>${formField('Fecha inicio','Fecha de inicio',day?iso(day):iso(pval('Fecha inicio')),'date',`min="${lo}" max="${hi}"`)}${formField('Hora inicio','Hora de inicio',clock(pval('Hora inicio')),'time')}${formField('Fecha fin','Fecha de fin',iso(pval('Fecha fin')),'date',`min="${lo}" max="${hi}"`)}${formField('Hora fin','Hora de fin',clock(pval('Hora fin')),'time')}${formField('Lugar','Lugar',pval('Lugar'),'text','maxlength="400"')}${formField('Personas','Con quién',pval('Personas'),'text','maxlength="400"')}${formField('Depende de','Qué falta o de qué depende',pval('Depende de'),'text','maxlength="1500"')}${formField('Coste previsto (€)','Coste previsto (€)',pval('Coste previsto (€)'),'number','min="0" max="1000000" step="0.01"')}${formField('Enlace','Enlace',pval('Enlace'),'url','maxlength="2000" pattern="https://.*"')}<label class="vac-field vac-wide">Notas<textarea name="Notas" rows="5" maxlength="8000">${esc(pval('Notas'))}</textarea></label></div><p class="vac-form-help">Deja fecha y hora vacías si aún están por acordar. Confirmar un plan requiere fecha; la hora puede quedar pendiente. Los cambios se guardan en el viaje.</p>${p?.Referencias?`<p class="vac-references">Referencias: ${esc(p.Referencias)}</p>`:''}</fieldset><p id="vac-save-status" role="status"></p><div class="vac-editor-actions"><button class="button light" type="button" data-vac-close>Cancelar</button><button class="button dark" type="submit">Guardar plan</button></div></form>`;
  dialog.showModal();dialog.querySelector('input[name="Plan"]').focus();
 }
 async function save(e){e.preventDefault();if(pending||!editor)return;const form=e.target;
  const fields=Object.fromEntries(new FormData(form));if(fields['Coste previsto (€)']!=='')fields['Coste previsto (€)']=Number(fields['Coste previsto (€)']);
  editor.payload ||= {requestId:crypto.randomUUID(),id:editor.id,version:editor.version,fields};
  pending=true;form.querySelector('fieldset').disabled=true;form.querySelector('[type="submit"]').disabled=true;const current=epoch;
  const msg=dialog.querySelector('#vac-save-status');msg.textContent='Guardando y comprobando…';
  try{const result=await api('saveVacationPlan',editor.payload);if(current!==epoch)return;if(!result.verified)throw new Error('No se ha confirmado el guardado.');data=result.data;editor.dirty=false;dialog.close();dialog.innerHTML='';editor=null;error='';draw();}
  catch(e){if(current!==epoch)return;msg.textContent=e.message+' Puedes reintentar el mismo guardado o cancelar y comparar con la fuente.';form.querySelector('[type="submit"]').textContent='Reintentar guardado';}
  finally{if(current===epoch){pending=false;form.querySelector('[type="submit"]')?.removeAttribute('disabled');}}
 }
 document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b||!host?.isConnected||!data)return;if(b.hasAttribute('data-vac-new'))edit();else if(b.dataset.vacNewDay)edit(null,Number(b.dataset.vacNewDay));else if(b.dataset.vacEdit)edit(b.dataset.vacEdit);else if(b.dataset.vacDay){selected=b.dataset.vacDay;draw();}else if(b.hasAttribute('data-vac-refresh'))refresh();});
 document.addEventListener('change',e=>{if(e.target.id==='vac-scope'){scope=e.target.value;draw();}});
 window.addEventListener('arc-auth-changed',()=>{epoch++;data=null;error='';loading=null;pending=false;editor=null;if(dialog){dialog.close();dialog.innerHTML='';}host=null;});
 window.ARC_VACATION=Object.freeze({mount(element,call){host=element;api=call;draw();if(!data&&!loading)refresh();},refresh,reset(){epoch++;data=null;host=null;loading=null;},iso,clock});
})();
